style.css:
@-moz-document domain("character.ai") {
/* 1. nuke google ad containers */
/* Targeted by ID and generic attribute for cross-browser reliability */
ins[id*="web_chat_page_top_anchor"], 
div[id*="google_ads_iframe"],
div[id^="ad-container"],
[id*="google_ads"],
iframe[src*="googleads"] {
    display: none !important;
    height: 0 !important;
    max-height: 0 !important;
    width: 0 !important;
    visibility: hidden !important;
    pointer-events: none !important;
    position: absolute !important;
    top: -9999px !important; /* ,ove it off-screen just in case display:none is bypassed */
}
/* 1.1. reclaim the screen */
body, 
#root, 
#next, 
.main-wrapper, 
main {
    padding-top: 0 !important;
    margin-top: 0 !important;
    border-top: none !important;
}
/* 1.2. personal fix for me (150% zoom fix)*/
header {
    max-height: 60px !important; /* Forces the header to stay slim */
}

/* 2. clean ghost elements */
/* Removes empty containers or 'end-cards' that appear after an ad is blocked. */
.outer-wrapper.assetless,
.creative.end-card,
.creative:not(.interstitial),
[data-google-query-id],
[data-ck-tag] {
    display: none !important;
    opacity: 0 !important;
}

/* 3. for layout stability */
/* This stops the page from "jumping" when the ad tries to load. */
html {
    scroll-behavior: smooth;
    overflow-y: overlay !important; /* Keeps scrollbar from shifting layout */
  }
}
